INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES (
  'ripeam',
  'navegacao-aguas-restritas',
  'Navegação em Águas Restritas',
  'RIPEAM / COLREG — Regras, Luzes, Marcas e Sinais',
  'Treinamento visual do RIPEAM/COLREG com regras de governo e navegação, luzes, marcas diurnas, sinais sonoros, visibilidade restrita e pegadinhas de prova.',
  $RIPEAM$[{"id":"R01","code":"REGRA 1","name":"Aplicação","category":"rules","pt":"Aplica-se a todas as embarcações em alto-mar e águas a ele ligadas navegáveis por navios de alto-mar.","en":"Applies to all vessels upon the high seas and in all waters connected therewith navigable by seagoing vessels."},{"id":"R02","code":"REGRA 2","name":"Responsabilidade","category":"rules","pt":"Nenhuma regra dispensa embarcação, proprietário, comandante ou tripulação das consequências de negligência; circunstâncias especiais podem exigir afastamento das regras para evitar perigo imediato.","en":"Nothing exonerates a vessel, owner, master or crew from consequences of neglect; special circumstances may require departure from the Rules to avoid immediate danger."},{"id":"R03","code":"REGRA 3","name":"Definições gerais","category":"rules","pt":"Reúne as definições fundamentais do RIPEAM, incluindo embarcação, propulsão mecânica, vela, pesca, sem governo, capacidade de manobra restrita, restrita pelo calado, em movimento e visibilidade restrita.","en":"Defines core COLREG terms including vessel, power-driven vessel, sailing vessel, fishing vessel, not under command, restricted in ability to manoeuvre, constrained by draught, underway and restricted visibility."},{"id":"R04","code":"REGRA 4","name":"Aplicação — Seção I","category":"rules","pt":"As Regras 4 a 10 aplicam-se em qualquer condição de visibilidade.","en":"Rules 4 to 10 apply in any condition of visibility."},{"id":"R05","code":"REGRA 5","name":"Vigilância","category":"rules","pt":"Toda embarcação deve manter permanentemente vigilância apropriada visual, auditiva e por todos os meios adequados.","en":"Every vessel shall at all times maintain a proper look-out by sight, hearing and all available means."},{"id":"R06","code":"REGRA 6","name":"Velocidade de segurança","category":"rules","pt":"Navegar permanentemente em velocidade segura, permitindo ação eficaz para evitar colisão e parada em distância apropriada às circunstâncias.","en":"Proceed at a safe speed so proper and effective action can be taken to avoid collision and the vessel can be stopped within an appropriate distance."},{"id":"R07","code":"REGRA 7","name":"Risco de abalroamento","category":"rules","pt":"Devem ser usados todos os meios apropriados para determinar o risco; em caso de dúvida, presume-se que ele existe.","en":"Use all available means to determine risk of collision; if there is any doubt, such risk shall be deemed to exist."},{"id":"R08","code":"REGRA 8","name":"Manobras para evitar abalroamento","category":"rules","pt":"A manobra deve ser positiva, feita com ampla antecedência e suficientemente ampla para ser claramente percebida; pequenas alterações sucessivas devem ser evitadas.","en":"Action to avoid collision shall be positive, made in ample time and large enough to be readily apparent; avoid a succession of small alterations."},{"id":"R09","code":"REGRA 9","name":"Canais estreitos","category":"rules","pt":"Ao navegar ao longo de canal estreito ou via de acesso, mantenha-se tão próximo quanto possível e seguro do limite exterior a boreste.","en":"In a narrow channel or fairway, keep as near to the outer limit on the starboard side as is safe and practicable.","visual":{"type":"channel"}},{"id":"R10","code":"REGRA 10","name":"Esquemas de separação de tráfego","category":"rules","pt":"Use a via apropriada no sentido geral do fluxo; ao cruzar, faça-o com rumo tão próximo quanto possível da perpendicular ao fluxo.","en":"Use the appropriate traffic lane in the general direction of traffic flow; if crossing, do so on a heading as nearly as practicable at right angles to the flow.","visual":{"type":"tss"}},{"id":"R11","code":"REGRA 11","name":"Aplicação — Seção II","category":"rules","pt":"As Regras 11 a 18 aplicam-se às embarcações no visual uma da outra.","en":"Rules 11 to 18 apply to vessels in sight of one another."},{"id":"R12","code":"REGRA 12","name":"Embarcações a vela","category":"rules","pt":"Com vento em bordos diferentes, a embarcação que recebe o vento por bombordo mantém-se fora do caminho; com vento no mesmo bordo, a de barlavento mantém-se fora da de sotavento.","en":"With wind on different sides, the vessel with wind on the port side keeps out of the way; with wind on the same side, the windward vessel keeps out of the way of the leeward vessel."},{"id":"R13","code":"REGRA 13","name":"Ultrapassagem","category":"rules","pt":"Toda embarcação que ultrapassa outra deve manter-se fora do caminho até estar inteiramente ultrapassada e suficientemente afastada. Considera-se ultrapassagem quando vem de mais de 22,5° para ré do través.","en":"Any vessel overtaking another shall keep out of the way until finally past and clear. Overtaking is from a direction more than 22.5° abaft the beam.","visual":{"type":"overtaking"}},{"id":"R14","code":"REGRA 14","name":"Situação de roda a roda","category":"rules","pt":"Duas embarcações de propulsão mecânica em rumos opostos ou quase opostos, com risco de abalroamento: ambas guinam para boreste e passam bombordo com bombordo.","en":"Two power-driven vessels meeting on reciprocal or nearly reciprocal courses with risk of collision: each alters course to starboard so they pass port-to-port.","visual":{"type":"headon"}},{"id":"R15","code":"REGRA 15","name":"Rumos cruzados","category":"rules","pt":"Entre duas embarcações de propulsão mecânica em rumos cruzados com risco, a que avista a outra por boreste deve manter-se fora do caminho e, se possível, evitar cruzar sua proa.","en":"When two power-driven vessels are crossing with risk of collision, the vessel which has the other on her starboard side shall keep out of the way and, if possible, avoid crossing ahead.","visual":{"type":"crossing"}},{"id":"R16","code":"REGRA 16","name":"Embarcação obrigada a manobrar","category":"rules","pt":"A embarcação obrigada a manter-se fora do caminho deve, tanto quanto possível, manobrar antecipada e substancialmente.","en":"The give-way vessel shall, so far as possible, take early and substantial action to keep well clear."},{"id":"R17","code":"REGRA 17","name":"Embarcação que tem preferência","category":"rules","pt":"A embarcação que tem preferência mantém rumo e velocidade; pode agir quando a outra não manobra apropriadamente e deve agir quando a colisão não puder ser evitada apenas pela manobra da obrigada.","en":"The stand-on vessel shall keep course and speed; may act when the give-way vessel is not taking appropriate action and shall act when collision cannot be avoided by the give-way vessel alone."},{"id":"R18","code":"REGRA 18","name":"Responsabilidade entre embarcações","category":"rules","pt":"Salvo exceções das Regras 9, 10 e 13, estabelece a hierarquia de responsabilidades entre propulsão mecânica, vela, pesca, sem governo, manobra restrita e restrita pelo calado.","en":"Subject to Rules 9, 10 and 13, establishes responsibilities among power-driven, sailing, fishing, not-under-command, restricted-in-ability-to-manoeuvre and constrained-by-draught vessels."},{"id":"R19","code":"REGRA 19","name":"Visibilidade restrita","category":"rules","pt":"Aplica-se a embarcações fora do visual em ou próximo de área de visibilidade restrita; velocidade segura, máquinas prontas e cautela especial nas manobras por radar.","en":"Applies to vessels not in sight of one another in or near restricted visibility; safe speed, engines ready and special caution with radar-based manoeuvres.","visual":{"type":"radar"}},{"id":"R21-MAST","code":"REGRA 21(a)","name":"Luz de mastro","category":"lights","pt":"Luz branca contínua no eixo longitudinal, setor horizontal de 225°: da proa até 22,5° por ante-a-ré do través em ambos os bordos.","en":"White continuous light over the fore-and-aft centreline, 225° sector from right ahead to 22.5° abaft the beam on either side.","visual":{"type":"sector","sector":"mast"}},{"id":"R21-SIDE","code":"REGRA 21(b)","name":"Luzes de bordos","category":"lights","pt":"Verde a boreste e encarnada a bombordo, cada uma visível em 112,5°: da proa até 22,5° por ante-a-ré do través do respectivo bordo.","en":"Green to starboard and red to port, each visible through 112.5° from right ahead to 22.5° abaft the beam.","visual":{"type":"sector","sector":"side"}},{"id":"R21-STERN","code":"REGRA 21(c)","name":"Luz de alcançado","category":"lights","pt":"Luz branca contínua próxima da popa, setor horizontal de 135°, cobrindo 67,5° para cada bordo a partir da popa.","en":"White continuous light near the stern, 135° sector, showing 67.5° from right aft on each side.","visual":{"type":"sector","sector":"stern"}},{"id":"R21-TOW","code":"REGRA 21(d)","name":"Luz de reboque","category":"lights","pt":"Luz amarela com as mesmas características da luz de alcançado.","en":"Yellow light having the same characteristics as the sternlight.","visual":{"type":"lights","lights":["yellow"],"layout":"single"}},{"id":"R21-ALL","code":"REGRA 21(e)","name":"Luz circular","category":"lights","pt":"Luz contínua visível em arco de horizonte de 360°.","en":"A continuous light visible over an arc of the horizon of 360°.","visual":{"type":"lights","lights":["white"],"layout":"single"}},{"id":"R23-PD","code":"REGRA 23","name":"Propulsão mecânica em movimento","category":"lights","pt":"Uma luz de mastro a vante; segunda luz de mastro a ré e mais alta (dispensada para menos de 50 m); luzes de bordos e luz de alcançado.","en":"Power-driven vessel underway: forward masthead light; second masthead light abaft and higher (not compulsory under 50 m); sidelights and sternlight.","visual":{"type":"vessel","kind":"power","lights":["white","white","red","green"]}},{"id":"R24-TOW2","code":"REGRA 24","name":"Reboque ≤ 200 m","category":"lights","pt":"Duas luzes de mastro em linha vertical, luzes de bordos, luz de alcançado e luz de reboque amarela acima da luz de alcançado.","en":"Towing not over 200 m: two masthead lights in a vertical line, sidelights, sternlight and yellow towing light above the sternlight.","visual":{"type":"vessel","kind":"tow","lights":["white","white","yellow"]}},{"id":"R24-TOW3","code":"REGRA 24","name":"Reboque > 200 m","category":"lights","pt":"Três luzes de mastro em linha vertical e marca de losango, além das demais luzes prescritas para reboque.","en":"Towing over 200 m: three masthead lights in a vertical line and a diamond day shape, in addition to the other towing lights.","visual":{"type":"vessel","kind":"tow","lights":["white","white","white","yellow"]}},{"id":"R25-SAIL","code":"REGRA 25","name":"Embarcação a vela em movimento","category":"lights","pt":"Luzes de bordos e luz de alcançado; pode exibir no tope duas luzes circulares em linha vertical, encarnada sobre verde, observadas as condições da Regra 25.","en":"Sailing vessel underway: sidelights and sternlight; may additionally show red over green all-round lights near the masthead subject to Rule 25.","visual":{"type":"vessel","kind":"sail","lights":["red","green"]}},{"id":"R26-TRAWL","code":"REGRA 26(b)","name":"Pesca de arrasto","category":"lights","pt":"Duas luzes circulares em linha vertical: verde sobre branca. Quando com seguimento, também luzes de bordo e alcançado.","en":"Trawling: two all-round lights in a vertical line, green over white. When making way, also sidelights and sternlight.","visual":{"type":"vessel","kind":"fishing","lights":["green","white"]}},{"id":"R26-FISH","code":"REGRA 26(c)","name":"Pesca que não seja de arrasto","category":"lights","pt":"Duas luzes circulares em linha vertical: encarnada sobre branca. Quando com seguimento, também luzes de bordo e alcançado.","en":"Fishing other than trawling: two all-round lights in a vertical line, red over white. When making way, also sidelights and sternlight.","visual":{"type":"vessel","kind":"fishing","lights":["red","white"]}},{"id":"R27-NUC","code":"REGRA 27(a)","name":"Embarcação sem governo","category":"lights","pt":"Duas luzes circulares encarnadas em linha vertical; de dia, duas esferas. Quando com seguimento, também luzes de bordo e alcançado.","en":"Vessel not under command: two all-round red lights in a vertical line; by day, two balls. When making way, also sidelights and sternlight.","visual":{"type":"vessel","kind":"special","lights":["red","red"]}},{"id":"R27-RAM","code":"REGRA 27(b)","name":"Capacidade de manobra restrita","category":"lights","pt":"Três luzes circulares em linha vertical: encarnada, branca, encarnada; de dia, esfera-losango-esfera.","en":"Restricted in ability to manoeuvre: three all-round lights in a vertical line, red-white-red; by day, ball-diamond-ball.","visual":{"type":"vessel","kind":"special","lights":["red","white","red"]}},{"id":"R27-DREDGE-BLOCK","code":"REGRA 27(d)","name":"Dragagem — bordo obstruído","category":"lights","pt":"Duas luzes circulares encarnadas ou duas esferas em linha vertical indicam o bordo da obstrução.","en":"Dredging — obstructed side: two all-round red lights or two balls in a vertical line indicate the obstructed side.","visual":{"type":"vessel","kind":"dredge","lights":["red","red"]}},{"id":"R27-DREDGE-PASS","code":"REGRA 27(d)","name":"Dragagem — bordo de passagem","category":"lights","pt":"Duas luzes circulares verdes ou dois losangos em linha vertical indicam o bordo pelo qual outra embarcação pode passar.","en":"Dredging — safe side: two all-round green lights or two diamonds in a vertical line indicate the side on which another vessel may pass.","visual":{"type":"vessel","kind":"dredge","lights":["green","green"]}},{"id":"R27-MINES","code":"REGRA 27(f)","name":"Remoção de minas","category":"lights","pt":"Três luzes circulares verdes ou três esferas: uma próxima do tope do mastro de vante e uma em cada lais da verga. É perigoso aproximar-se a menos de 1.000 m.","en":"Mineclearance: three all-round green lights or three balls, one near the foremast head and one at each end of the fore yard. It is dangerous to approach within 1,000 m.","visual":{"type":"vessel","kind":"mine","lights":["green","green","green"]}},{"id":"R28-CBD","code":"REGRA 28","name":"Restrita devido ao calado","category":"lights","pt":"Pode exibir três luzes circulares encarnadas em linha vertical ou, de dia, um cilindro, além das luzes de propulsão mecânica.","en":"A vessel constrained by her draught may show three all-round red lights in a vertical line or, by day, a cylinder, in addition to power-driven vessel lights.","visual":{"type":"vessel","kind":"special","lights":["red","red","red"]}},{"id":"R29-PILOT","code":"REGRA 29","name":"Praticagem","category":"lights","pt":"Duas luzes circulares em linha vertical no ou próximo do tope do mastro: branca sobre encarnada; em movimento, também bordos e alcançado.","en":"Pilot vessel on pilotage duty: two all-round lights in a vertical line at or near the masthead, white over red; when underway, also sidelights and sternlight.","visual":{"type":"vessel","kind":"pilot","lights":["white","red"]}},{"id":"R30-ANCH","code":"REGRA 30","name":"Fundeada","category":"lights","pt":"Luz circular branca a vante e outra branca a ré em nível mais baixo; embarcação menor que 50 m pode exibir apenas uma luz circular branca. De dia: esfera.","en":"At anchor: all-round white light forward and another aft at a lower level; under 50 m may show one all-round white light. By day: one ball.","visual":{"type":"vessel","kind":"anchor","lights":["white","white"]}},{"id":"R30-AGROUND","code":"REGRA 30(d)","name":"Encalhada","category":"lights","pt":"Além dos sinais de fundeio, duas luzes circulares encarnadas em linha vertical; de dia, três esferas em linha vertical.","en":"Aground: in addition to anchor signals, two all-round red lights in a vertical line; by day, three balls in a vertical line.","visual":{"type":"vessel","kind":"aground","lights":["red","red"]}},{"id":"SH-BALL","code":"Regra 30","name":"Esfera — fundeada","category":"shapes","pt":"Uma esfera é a marca diurna de embarcação fundeada.","en":"One ball is the day shape for a vessel at anchor.","visual":{"type":"shapes","shapes":["ball"]}},{"id":"SH-2BALL","code":"Regra 27(a)","name":"Duas esferas — sem governo","category":"shapes","pt":"Duas esferas em linha vertical indicam embarcação sem governo.","en":"Two balls in a vertical line indicate a vessel not under command.","visual":{"type":"shapes","shapes":["ball","ball"]}},{"id":"SH-BDB","code":"Regra 27(b)","name":"Esfera–losango–esfera — RAM","category":"shapes","pt":"Esfera, losango e esfera em linha vertical indicam embarcação com capacidade de manobra restrita.","en":"Ball-diamond-ball in a vertical line indicates a vessel restricted in her ability to manoeuvre.","visual":{"type":"shapes","shapes":["ball","diamond","ball"]}},{"id":"SH-CYL","code":"Regra 28","name":"Cilindro — restrita pelo calado","category":"shapes","pt":"Um cilindro é a marca que uma embarcação restrita devido ao calado pode exibir.","en":"A cylinder is the day shape a vessel constrained by her draught may exhibit.","visual":{"type":"shapes","shapes":["cylinder"]}},{"id":"SH-CONE-DOWN","code":"Regra 25(e)","name":"Cone vértice para baixo — vela + motor","category":"shapes","pt":"Embarcação navegando a vela e usando também propulsão mecânica deve exibir a vante um cone com vértice para baixo.","en":"A vessel proceeding under sail while also using machinery shall exhibit forward a cone apex downwards.","visual":{"type":"shapes","shapes":["coneDown"]}},{"id":"SH-2CONE","code":"Regra 26","name":"Dois cones unidos pelos vértices — pesca","category":"shapes","pt":"Dois cones unidos pelos vértices, em linha vertical, são marca diurna de embarcação engajada na pesca.","en":"Two cones with apexes together in a vertical line are the day shape for a vessel engaged in fishing.","visual":{"type":"shapes","shapes":["coneUp","coneDown"]}},{"id":"SH-3BALL","code":"Regra 30(d)","name":"Três esferas — encalhada","category":"shapes","pt":"Três esferas em linha vertical, além da marca de fundeio aplicável, identificam embarcação encalhada.","en":"Three balls in a vertical line, in addition to applicable anchor signals, identify a vessel aground.","visual":{"type":"shapes","shapes":["ball","ball","ball"]}},{"id":"SH-DIAMOND","code":"Regra 24","name":"Losango — reboque > 200 m","category":"shapes","pt":"Quando o comprimento do reboque for superior a 200 m, deve ser exibida uma marca em forma de losango onde melhor possa ser vista.","en":"When the length of tow exceeds 200 m, a diamond shape shall be displayed where it can best be seen.","visual":{"type":"shapes","shapes":["diamond"]}},{"id":"S34-1S","code":"REGRA 34(a)","name":"1 apito curto","category":"sounds","pt":"Estou guinando para boreste.","en":"I am altering my course to starboard.","visual":{"type":"sound","pattern":["short"]}},{"id":"S34-2S","code":"REGRA 34(a)","name":"2 apitos curtos","category":"sounds","pt":"Estou guinando para bombordo.","en":"I am altering my course to port.","visual":{"type":"sound","pattern":["short","short"]}},{"id":"S34-3S","code":"REGRA 34(a)","name":"3 apitos curtos","category":"sounds","pt":"Estou dando a ré.","en":"I am operating astern propulsion.","visual":{"type":"sound","pattern":["short","short","short"]}},{"id":"S34-OV-STB","code":"REGRA 34(c)","name":"2 longos + 1 curto","category":"sounds","pt":"Em canal estreito: tenciono ultrapassá-la por seu boreste.","en":"In a narrow channel: I intend to overtake you on your starboard side.","visual":{"type":"sound","pattern":["long","long","short"]}},{"id":"S34-OV-PORT","code":"REGRA 34(c)","name":"2 longos + 2 curtos","category":"sounds","pt":"Em canal estreito: tenciono ultrapassá-la por seu bombordo.","en":"In a narrow channel: I intend to overtake you on your port side.","visual":{"type":"sound","pattern":["long","long","short","short"]}},{"id":"S34-AGREE","code":"REGRA 34(c)","name":"Longo–curto–longo–curto","category":"sounds","pt":"Concordo com sua ultrapassagem em canal estreito.","en":"I agree to your overtaking in a narrow channel.","visual":{"type":"sound","pattern":["long","short","long","short"]}},{"id":"S34-DOUBT","code":"REGRA 34(d)","name":"≥ 5 apitos curtos","category":"sounds","pt":"Dúvida quanto às intenções ou ações da outra embarcação, ou dúvida se ela está tomando ação suficiente para evitar abalroamento.","en":"Doubt about the other vessel's intentions/actions or whether sufficient action is being taken to avoid collision.","visual":{"type":"sound","pattern":["short","short","short","short","short"]}},{"id":"S34-BEND","code":"REGRA 34(e)","name":"1 apito longo","category":"sounds","pt":"Aproximação de curva ou área de canal estreito onde outras embarcações possam estar ocultas; deve ser respondido por um apito longo do outro lado.","en":"Approaching a bend or area of a narrow channel where other vessels may be obscured; answered by one prolonged blast from the other side.","visual":{"type":"sound","pattern":["long"]}},{"id":"S35-MAKING","code":"REGRA 35(a)","name":"1 longo / ≤ 2 min","category":"sounds","pt":"Propulsão mecânica com seguimento em visibilidade restrita.","en":"Power-driven vessel making way through the water in restricted visibility.","visual":{"type":"sound","pattern":["long"]}},{"id":"S35-STOPPED","code":"REGRA 35(b)","name":"2 longos / ≤ 2 min","category":"sounds","pt":"Propulsão mecânica sob máquinas, mas parada e sem seguimento; os dois longos são separados por cerca de 2 s.","en":"Power-driven vessel underway but stopped and making no way; two prolonged blasts separated by about 2 seconds.","visual":{"type":"sound","pattern":["long","long"]}},{"id":"S35-SPECIAL","code":"REGRA 35(c)(d)","name":"1 longo + 2 curtos / ≤ 2 min","category":"sounds","pt":"Sinal de visibilidade restrita para sem governo, restrita pelo calado, vela, pesca, manobra restrita, rebocando ou empurrando, conforme a Regra 35.","en":"Restricted-visibility signal for NUC, constrained by draught, sailing, fishing, RAM, towing or pushing vessels as provided by Rule 35.","visual":{"type":"sound","pattern":["long","short","short"]}},{"id":"S35-TOWED","code":"REGRA 35(e)","name":"1 longo + 3 curtos / ≤ 2 min","category":"sounds","pt":"Embarcação rebocada, ou a última do reboque se houver mais de uma, quando guarnecida, se possível logo após o sinal do rebocador.","en":"A vessel towed, or the last vessel of the tow if more than one and manned, if practicable immediately after the towing vessel's signal.","visual":{"type":"sound","pattern":["long","short","short","short"]}},{"id":"S35-PILOT","code":"REGRA 35(k)","name":"4 apitos curtos","category":"sounds","pt":"Embarcação de praticagem engajada em serviço pode soar quatro curtos como sinal de identificação, além do sinal aplicável.","en":"A pilot vessel engaged on pilotage duty may sound four short blasts as an identity signal in addition to the applicable signal.","visual":{"type":"sound","pattern":["short","short","short","short"]}},{"id":"R32-SHORT","code":"REGRA 32","name":"Apito curto","category":"Duração aproximada de 1 segundo.","pt":"A short blast has a duration of about one second.","en":{"type":"sound","pattern":["short"]}},{"id":"R32-LONG","code":"REGRA 32","name":"Apito longo","category":"Duração de 4 a 6 segundos.","pt":"A prolonged blast has a duration of four to six seconds.","en":{"type":"sound","pattern":["long"]}},{"id":"TRAP-13","code":"REGRA 13","name":"Pegadinha: alteração posterior de marcação","category":"traps","pt":"Uma alteração posterior de marcação não transforma a alcançadora em embarcação de rumos cruzados nem a libera da obrigação até estar inteiramente ultrapassada e suficientemente afastada.","en":"A subsequent alteration of bearing does not make the overtaking vessel a crossing vessel or relieve her duty until finally past and clear.","tags":["exam"]},{"id":"TRAP-14","code":"REGRA 14","name":"Pegadinha: dúvida na roda a roda","category":"traps","pt":"Havendo dúvida sobre a existência de situação de roda a roda, deve-se considerá-la existente e manobrar de acordo.","en":"When in doubt whether a head-on situation exists, assume it does and act accordingly.","tags":["exam"]},{"id":"TRAP-15","code":"REGRA 15","name":"Pegadinha: cruzar a proa","category":"traps","pt":"A embarcação que avista a outra por boreste deve manter-se fora do caminho e, se as circunstâncias permitirem, evitar cruzar a proa da outra.","en":"The vessel which has the other on her starboard side shall keep out of the way and, if circumstances admit, avoid crossing ahead.","tags":["exam"]},{"id":"TRAP-19","code":"REGRA 19(d)","name":"Pegadinha: radar e alteração para bombordo","category":"traps","pt":"Ao detectar apenas por radar uma embarcação por ante-a-vante do través, deve-se evitar, tanto quanto possível, alteração para bombordo, exceto se a outra estiver sendo alcançada.","en":"When detecting another vessel by radar alone forward of the beam, avoid, so far as possible, an alteration to port, except for a vessel being overtaken.","visual":{"type":"radar"},"tags":["exam"]},{"id":"TRAP-20","code":"REGRA 20","name":"Pegadinha: luzes e marcas","category":"traps","pt":"As regras de luzes aplicam-se do pôr ao nascer do Sol; em visibilidade restrita, as luzes prescritas também são exibidas entre nascer e pôr do Sol. As marcas aplicam-se de dia.","en":"Light Rules apply from sunset to sunrise; in restricted visibility prescribed lights are also shown from sunrise to sunset. Shapes apply by day.","tags":["exam"]},{"id":"TRAP-27","code":"REGRA 27(f)","name":"Pegadinha: remoção de minas","category":"traps","pt":"As três luzes verdes/esferas indicam perigo de aproximação a menos de 1.000 m da embarcação em remoção de minas.","en":"The three green lights/balls indicate it is dangerous to approach within 1,000 m of a mineclearance vessel.","tags":["exam"]}]$RIPEAM$::jsonb,
  TRUE,
  20,
  NOW()
)
ON CONFLICT (slug) DO UPDATE SET
  subject_slug=EXCLUDED.subject_slug,
  subject_label=EXCLUDED.subject_label,
  title=EXCLUDED.title,
  description=EXCLUDED.description,
  cards=EXCLUDED.cards,
  is_active=TRUE,
  sort_order=EXCLUDED.sort_order,
  updated_at=NOW();

SELECT slug, title, jsonb_array_length(cards) AS total_cartoes
FROM decks WHERE slug='ripeam';
